mapper.select:
SELECT T1.RULE_ID ruleId, T1.IND_ID indId, T2.IND_NAME indName, T2.SUP_TYPE supType, T2.WARN_COND warnCond, T2.FOUL_COND foulCond, T2.APPROVE_COND approveCond, T2.IND_TYPE indType FROM RSK_RULE_INDICATOR T1 INNER JOIN RSK_ISUP_INDICATOR T2 ON T1.IND_ID = T2.IND_ID
T1.RULE_ID = #{ruleId,jdbcType=VARCHAR}
AND T2.IND_NAME like concat('%',concat(#{indName,jdbcType=VARCHAR},'%'))

SELECT
count(0)
FROM RSK_RULE_INFO
where RULE_NAME = #{ruleName} 
and RULE_ID != #{ruleId}
